test('general/block-inside-switch-inside-loop/exec.js', async () => {
  const source =
    "// it shouldn't break on a case-break statement\nvar i;\nfor (i = 0; i < 10; i++) {\n  switch (i) {\n    case 1: {\n      break;\n    }\n  }\n\n  const z = 3; // to force the plugin to convert to loop function call\n  () => z;\n}\n\nexpect(i).toBe(10);\n\n// it should continue on continue statements within switch\nvar j = 0;\nfor (i = 0; i < 10; i++) {\n  switch (i) {\n    case 0: {\n      continue;\n    }\n  }\n  j++;\n\n  const z = 3;\n  () => z;\n}\n\nexpect(j).toBe(9);\n\n// it should work with loops nested within switch\nj = 0;\nfor (i = 0; i < 10; i++) {\n  switch (i) {\n    case 0: {\n      for (var k = 0; k < 10; k++) {\n        const z = 3;\n        () => z;\n        j++;\n        break;\n      }\n      break;\n    }\n  }\n\n  const z = 3;\n  () => z;\n}\n\nexpect(j).toBe(1);\n";
  expect(await transformOutcome(source, 'exec.js', { transforms: { blockScoping: true } }))
    .toMatchInlineSnapshot(`
    "// it shouldn't break on a case-break statement
    var i;
    var _loopResult;
    var _loop = () => {
      switch (i) {
        case 1: {
          break;
        }
      }
      var z = 3;
      () => z;
      return {
        type: 'normal',
        vars: [],
      };
    };
    for (i = 0; i < 10; i++) {
      _loopResult = _loop();
    }
    expect(i).toBe(10);
    // it should continue on continue statements within switch
    var j = 0;
    var _loopResult7;
    var _loop6 = () => {
      switch (i) {
        case 0: {
          return {
            type: 'continue',
            vars: [],
          };
        }
      }
      j++;
      var z = 3;
      () => z;
      return {
        type: 'normal',
        vars: [],
      };
    };
    for (i = 0; i < 10; i++) {
      _loopResult7 = _loop6();
      if (_loopResult7.type === 'continue') continue;
    }
    expect(j).toBe(9);
    // it should work with loops nested within switch
    j = 0;
    var _loopResult9;
    var _loop8 = () => {
      switch (i) {
        case 0: {
          var _loopResult11;
          var _loop10 = () => {
            var _z = 3;
            () => _z;
            j++;
            return {
              type: 'break',
              vars: [],
            };
            return {
              type: 'normal',
              vars: [],
            };
          };
          for (var k = 0; k < 10; k++) {
            _loopResult11 = _loop10();
            if (_loopResult11.type === 'break') break;
          }
          break;
        }
      }
      var z = 3;
      () => z;
      return {
        type: 'normal',
        vars: [],
      };
    };
    for (i = 0; i < 10; i++) {
      _loopResult9 = _loop8();
    }
    expect(j).toBe(1);"
  `);
});

