    'expect(() => {\n  for (const a of [1]) {\n    switch (true) {\n      case true: {\n        const b = 1;\n        () => b;\n        if (true) break;\n        continue;\n      }\n      case false: {\n        throw new Error("unreachable");\n      }\n    }\n  }\n}).not.toThrow();\n';
