test('general/label-complex/input.js', async () => {
  const source =
    'outer: while (t) {\n  inner: while (t2) {\n    for (let i = 0; i < 3; i++) {\n      later(() => i);\n      if (test1) break outer;\n      else if (test2) break inner;\n      else if (test3) continue outer;\n      else if (test4) continue inner;\n      else if (test5) break;\n      else if (test6) continue;\n    }\n  }\n}\n';
  expect(await transformOutcome(source, 'input.js', { transforms: { blockScoping: true } }))
    .toMatchInlineSnapshot(`
    "outer: while (t) {
      inner: while (t2) {
        var _loopResult;
        var _loop = i => {
          later(() => i);
          if (test1) break outer;
          else if (test2) break inner;
          else if (test3) continue outer;
          else if (test4) continue inner;
          else if (test5)
            return {
              type: 'break',
              vars: [i],
            };
          else if (test6)
            return {
              type: 'continue',
              vars: [i],
            };
          return {
            type: 'normal',
            vars: [i],
          };
        };
        for (var i = 0; i < 3; i++) {
          _loopResult = _loop(i);
          i = _loopResult.vars[0];
          if (_loopResult.type === 'break') break;
          if (_loopResult.type === 'continue') continue;
        }
      }
    }"
  `);
});

