test('throwIfClosureRequired/for-const-closure/input.js', async () => {
  const source =
    'for (let i = 0; i < 5; i++) {\n  const l = i;\n  setTimeout(function() {\n    console.log(l);\n  }, 1);\n}\n';
  expect(await transformOutcome(source, 'input.js', { transforms: { blockScoping: true } }))
    .toMatchInlineSnapshot(`
    "var _loopResult;
    var _loop = i => {
      var l = i;
      setTimeout(function () {
        console.log(l);
      }, 1);
      return {
        type: 'normal',
        vars: [i],
      };
    };
    for (var i = 0; i < 5; i++) {
      _loopResult = _loop(i);
      i = _loopResult.vars[0];
    }"
  `);
});

